test("既定を当てる前の props のまま流れてきた値は、サイズを組み立てる入口に渡せない", () => {
  expectTypeOf<Props>().not.toExtend<Parameters<typeof Size.fromProps>[0]>();
});

test("既定を当てる前の props のまま流れてきた値は、固定の長さを読む入口に渡せない", () => {
  expectTypeOf<Props>().not.toExtend<
    Parameters<typeof Size.fixedLengthFromProps>[0]
  >();
});

test("既定を当てる前の props のまま流れてきた値は、サイズの宣言を作る入口に渡せない", () => {
  expectTypeOf<Props>().not.toExtend<
    Parameters<typeof Size.declarationsFromProps>[0]
  >();
});

test("既定を当てる前の props のまま流れてきた値は、下限と上限の逆転を集める入口に渡せない", () => {
  expectTypeOf<Props>().not.toExtend<
    Parameters<typeof Size.collectInvertedLimitAxes>[0]
  >();
});

test("既定を当てた props はサイズの読み出しに渡せる", () => {
  expectTypeOf<ResolvedProps<"Box">>().toExtend<ResolvedPropsReaderInput>();
  expectTypeOf<ResolvedProps<"Ellipse">>().toExtend<ResolvedPropsReaderInput>();
  expectTypeOf<
    ResolvedProps<PrimitiveType>
  >().toExtend<ResolvedPropsReaderInput>();
});

test("fill を集める・写す入口は、書かれたままの props を受け取る", () => {
  expectTypeOf<Props>().toExtend<Parameters<typeof Size.collectFillAxes>[0]>();
  expectTypeOf<Props>().toExtend<
    Parameters<typeof Size.collectFillPropEdits>[0]
  >();
  expectTypeOf<Props>().toExtend<
    Parameters<typeof Size.collectFillModePropEdits>[0][number]
  >();
  expectTypeOf<Props>().toExtend<
    Parameters<typeof Size.collectFillAxesInFreeParent>[0]
  >();
});

test("どの型でも、モードを書いていない軸は既定を当てても fill にならない", () => {
  expect(
    Object.values(PrimitiveTypes).filter(
      (type) =>
        Size.collectFillAxes(ResolvedProps.resolve(type, {})).length > 0,
    ),
  ).toEqual([]);
});

test("自由配置の親の下で両軸とも fill なら幅・高さの順で返る", () => {
  expect(
    Size.collectFillAxesInFreeParent(
      { widthMode: "fill", heightMode: "fill" },
      Layouts.Free,
    ),
  ).toEqual(["width", "height"]);
});

test("横並びの親の下では両軸とも fill でも軸は返らない", () => {
  expect(
    Size.collectFillAxesInFreeParent(
      { widthMode: "fill", heightMode: "fill" },
      Layouts.Row,
    ),
  ).toEqual([]);
});

test("縦並びの親の下では両軸とも fill でも軸は返らない", () => {
  expect(
    Size.collectFillAxesInFreeParent(
      { widthMode: "fill", heightMode: "fill" },
      Layouts.Column,
    ),
  ).toEqual([]);
});

test("hug の幅で最小が最大より大きいとき、幅が逆転として返る", () => {
  expect(
    Size.collectInvertedLimitAxes(
      ResolvedProps.resolve("Box", {
        widthMode: "hug",
        minWidth: 500,
        maxWidth: 100,
        heightMode: "hug",
      }),
    ),
  ).toEqual(["width"]);
});

type ResolvedPropsReaderInput = Parameters<typeof Size.fromProps>[0] &
  Parameters<typeof Size.fixedLengthFromProps>[0] &
  Parameters<typeof Size.declarationsFromProps>[0] &
  Parameters<typeof Size.collectInvertedLimitAxes>[0];

test("既定を当てる前の props のまま流れてきた値は、サイズを組み立てる入口に渡せない", () => {
  expectTypeOf<Props>().not.toExtend<Parameters<typeof Size.fromProps>[0]>();
});
